<?php
require __DIR__.'/includes/module.php';
$u=require_auth();require_permission('invoices.edit');$bid=(int)$u['business_id'];$pdo=db();
$q=$pdo->prepare('SELECT * FROM businesses WHERE id=?');$q->execute([$bid]);$business=$q->fetch();
$q=$pdo->prepare('SELECT id,name,company,email,phone,city,gstin,address,state,state_code,postal_code FROM customers WHERE business_id=? AND archived_at IS NULL ORDER BY name');$q->execute([$bid]);$customers=$q->fetchAll();
$q=$pdo->prepare('SELECT id,name,unit,price,tax_rate,hsn_sac FROM products WHERE business_id=? AND active=1 ORDER BY name');$q->execute([$bid]);$products=$q->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$cid=(int)($_POST['customer_id']??0);$cq=$pdo->prepare('SELECT * FROM customers WHERE id=? AND business_id=? AND archived_at IS NULL');$cq->execute([$cid,$bid]);$customer=$cq->fetch();
 $posState=trim((string)($_POST['place_of_supply_state']??''));$posCode=trim((string)($_POST['place_of_supply_code']??''));$date=trim((string)($_POST['invoice_date']??''));$due=trim((string)($_POST['due_date']??''))?:null;
 $regular=$business['gst_registration_type']==='Regular';$supplierCode=trim((string)($business['state_code']??''));$gstin=strtoupper(trim((string)($business['gstin']??'')));
 $lines=[];$subtotal=0.0;$taxTotal=0.0;$productsPosted=$_POST['product_id']??[];$qtyPosted=$_POST['quantity']??[];
 if(!$customer)$error='Choose an active customer from this workspace.';
 elseif($regular&&(!preg_match('/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/',$gstin)||!preg_match('/^[0-9]{2}$/',$supplierCode)||substr($gstin,0,2)!==$supplierCode||trim((string)$business['legal_name'])===''||trim((string)$business['address'])===''))$error='Complete the legal supplier name, address, valid GSTIN and matching state code in Settings before issuing GST invoices.';
 elseif($regular&&!empty($customer['gstin'])&&(!preg_match('/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/',strtoupper((string)$customer['gstin']))||trim((string)$customer['address'])===''))$error='Check the customer GSTIN and address, or clear the GSTIN for a consumer customer.';
 elseif($posState===''||!preg_match('/^[0-9]{2}$/',$posCode))$error='Enter the place of supply state and its two-digit GST state code.';
 elseif(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$error='Enter a valid invoice date.';
 else {
  foreach($productsPosted as $i=>$productId){$productId=(int)$productId;$qty=(float)($qtyPosted[$i]??0);if($productId<1||$qty<=0)continue;$pq=$pdo->prepare('SELECT id,name,unit,price,tax_rate,hsn_sac FROM products WHERE id=? AND business_id=? AND active=1');$pq->execute([$productId,$bid]);$p=$pq->fetch();if(!$p)continue;
   if($regular&&trim((string)$p['hsn_sac'])===''){$error='Add an HSN/SAC code to every catalog item before GST invoicing.';break;}
   $rate=$regular?(float)$p['tax_rate']:0.0;$base=round($qty*(float)$p['price'],2);$cgst=$sgst=$igst=0.0;$cgstRate=$sgstRate=$igstRate=0.0;
   if($regular){if($supplierCode===$posCode){$cgstRate=$sgstRate=$rate/2;$cgst=round($base*$cgstRate/100,2);$sgst=round($base*$sgstRate/100,2);}else{$igstRate=$rate;$igst=round($base*$rate/100,2);}}
   $tax=round($cgst+$sgst+$igst,2);$lines[]=['product_id'=>$productId,'description'=>$p['name'],'hsn_sac'=>$p['hsn_sac'],'quantity'=>$qty,'unit'=>$p['unit'],'rate'=>(float)$p['price'],'tax_rate'=>$rate,'cgst_rate'=>$cgstRate,'sgst_rate'=>$sgstRate,'igst_rate'=>$igstRate,'subtotal'=>$base,'cgst'=>$cgst,'sgst'=>$sgst,'igst'=>$igst,'tax'=>$tax];$subtotal+=$base;$taxTotal+=$tax;
  }
  if(!$error&&!$lines)$error='Add at least one active catalog item with a positive quantity.';
 }
 if(!$error){try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT id FROM businesses WHERE id=? FOR UPDATE');$lock->execute([$bid]);$dateObj=new DateTimeImmutable($date);$fyStart=(int)$dateObj->format('n')>=4?(int)$dateObj->format('Y'):(int)$dateObj->format('Y')-1;$fyLabel=$fyStart.'-'.substr((string)($fyStart+1),-2);$prefix='INV-'.$fyLabel.'-';$existing=$pdo->prepare('SELECT invoice_number FROM invoices WHERE business_id=? AND invoice_number LIKE ?');$existing->execute([$bid,$prefix.'%']);$seq=0;foreach($existing->fetchAll(PDO::FETCH_COLUMN) as $issuedNo)if(preg_match('/^'.preg_quote($prefix,'/').'([0-9]+)$/' ,(string)$issuedNo,$m))$seq=max($seq,(int)$m[1]);$number=$prefix.str_pad((string)($seq+1),4,'0',STR_PAD_LEFT);$total=round($subtotal+$taxTotal,2);$type=$regular?'GST Tax Invoice':($business['gst_registration_type']==='Composition'?'Bill of Supply':'Standard Invoice');$businessSnapshot=$business;$customerSnapshot=$customer;$businessSnapshot['gstin']=$regular?$gstin:null;$pdo->prepare("INSERT INTO invoices(business_id,customer_id,invoice_number,invoice_date,due_date,status,document_type,place_of_supply_state,place_of_supply_code,reverse_charge,subtotal,tax_total,total,customer_snapshot,business_snapshot,notes) VALUES(?,?,?,?,?,'Issued',?,?,?,0,?,?,?,?,?,?)")->execute([$bid,$cid,$number,$date,$due,$type,$posState,$posCode,$subtotal,$taxTotal,$total,json_encode($customerSnapshot,JSON_UNESCAPED_UNICODE),json_encode($businessSnapshot,JSON_UNESCAPED_UNICODE),trim((string)($_POST['notes']??''))]);$iid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO invoice_items(invoice_id,product_id,description,hsn_sac,quantity,unit,unit_price,tax_rate,cgst_rate,sgst_rate,igst_rate,line_subtotal,line_tax,cgst_amount,sgst_amount,igst_amount,line_total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($lines as $l)$ins->execute([$iid,$l['product_id'],$l['description'],$l['hsn_sac'],$l['quantity'],$l['unit'],$l['rate'],$l['tax_rate'],$l['cgst_rate'],$l['sgst_rate'],$l['igst_rate'],$l['subtotal'],$l['tax'],$l['cgst'],$l['sgst'],$l['igst'],$l['subtotal']+$l['tax']]);$pdo->commit();audit('invoice.issue',$number);flash('Invoice issued successfully.');redirect('invoice-view.php?id='.$iid);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Invoice could not be saved. Check the database migration and invoice details.';}}
}
$defaultCustomer=null;foreach($customers as $c)if((int)$c['id']===(int)($_GET['customer']??0))$defaultCustomer=$c;
page_start('Create invoice','invoices');module_css('invoice-create');?>
<style>.gst-hint{padding:11px 13px;border-radius:7px;background:#f1f8fc;color:#526879;font-size:10px;margin-bottom:12px}.invoice-line{display:grid;grid-template-columns:minmax(170px,2fr) 100px 90px 95px 35px;gap:8px;margin:7px 0}.invoice-line select,.invoice-line input{height:36px;border:1px solid #e5e9ed;border-radius:6px;padding:0 8px;font-size:10px;background:#fff}@media(max-width:650px){.invoice-line{grid-template-columns:1fr 75px 30px}.invoice-line .line-price,.invoice-line .line-tax{display:none}}</style>
<div class="section-head"><div><span class="eyebrow">BILLING</span><h1>Create invoice</h1><p>Catalog prices and tax rates are read from the server when you issue this invoice.</p></div><a class="button secondary" href="invoices.php">Cancel</a></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif?>
<form method="post" class="content-card simple-form" id="invoice-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><div class="gst-hint"><?=e($business['gst_registration_type'])?> · <?=e($business['legal_name']?:$business['name'])?><?=!empty($business['gstin'])?' · GSTIN '.e($business['gstin']):''?>. <?= $business['gst_registration_type']==='Regular'?'Tax split is computed from supplier and place-of-supply state codes.':'No GST tax is added under this profile.'?></div><div class="modal-form"><label>Customer *<select required name="customer_id" id="customer-select"><option value="">Choose a customer</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>" data-state="<?=e($c['state']??'')?>" data-code="<?=e($c['state_code']??'')?>" <?=((int)($_GET['customer']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'].($c['company']?' · '.$c['company']:''))?></option><?php endforeach?></select></label><label>Invoice date<input type="date" name="invoice_date" value="<?=e(date('Y-m-d'))?>" required></label><label>Due date<input type="date" name="due_date" value="<?=e(date('Y-m-d',strtotime('+14 days')))?>"></label><label>Place of supply state *<input name="place_of_supply_state" id="pos-state" required value="<?=e($defaultCustomer['state']??'')?>"></label><label>State code *<input name="place_of_supply_code" id="pos-code" required inputmode="numeric" maxlength="2" pattern="[0-9]{2}" value="<?=e($defaultCustomer['state_code']??'')?>"></label><label class="wide">Line items</label></div><div id="line-items" class="line-items"></div><button class="link-button" type="button" id="add-line"><i class="ti ti-plus"></i> Add catalog item</button><label class="form-notes">Notes / payment terms<textarea name="notes" placeholder="Payment instructions or additional notes"></textarea></label><div class="invoice-total"><span>Subtotal <b id="subtotal">₹ 0.00</b></span><span>CGST <b id="cgst-total">₹ 0.00</b></span><span>SGST <b id="sgst-total">₹ 0.00</b></span><span>IGST <b id="igst-total">₹ 0.00</b></span><strong>Invoice total <b id="grand-total">₹ 0.00</b></strong></div><button class="button primary"><i class="ti ti-file-invoice"></i> Issue invoice</button></form>
<template id="line-template"><div class="invoice-line"><select name="product_id[]" required><option value="">Select catalog item</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" data-price="<?=e($p['price'])?>" data-tax="<?=e($p['tax_rate'])?>" data-hsn="<?=e($p['hsn_sac']??'')?>"><?=e($p['name'].' · '.money($p['price']).' · '.$p['tax_rate'].'%')?></option><?php endforeach?></select><input name="quantity[]" type="number" min="0.001" step="0.001" value="1" required placeholder="Qty"><input class="line-price" readonly placeholder="Price"><input class="line-tax" readonly placeholder="GST %"><button type="button" class="link-button remove-line">×</button></div></template>
<script>const regular=<?= $business['gst_registration_type']==='Regular'?'true':'false' ?>,supplierCode=<?=json_encode($business['state_code']??'')?>,currency=<?=json_encode($business['currency'])?>;const root=document.getElementById('line-items');function addLine(){root.append(document.getElementById('line-template').content.cloneNode(true));calc()}document.getElementById('add-line').onclick=addLine;document.getElementById('customer-select').addEventListener('change',e=>{const o=e.target.selectedOptions[0];document.getElementById('pos-state').value=o.dataset.state||'';document.getElementById('pos-code').value=o.dataset.code||''});root.addEventListener('input',calc);root.addEventListener('change',calc);root.addEventListener('click',e=>{if(e.target.closest('.remove-line')){e.target.closest('.invoice-line').remove();calc()}});function fmt(n){return currency+' '+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}function calc(){let sub=0,cg=0,sg=0,ig=0;root.querySelectorAll('.invoice-line').forEach(row=>{let o=row.querySelector('select').selectedOptions[0],q=+row.querySelector('[name="quantity[]"]').value||0,p=+o?.dataset.price||0,t=regular?(+o?.dataset.tax||0):0;row.querySelector('.line-price').value=p?fmt(p):'';row.querySelector('.line-tax').value=t+'%';let base=q*p;sub+=base;if(regular&&document.getElementById('pos-code').value===supplierCode){cg+=base*t/200;sg+=base*t/200}else ig+=base*t/100});document.getElementById('subtotal').textContent=fmt(sub);document.getElementById('cgst-total').textContent=fmt(cg);document.getElementById('sgst-total').textContent=fmt(sg);document.getElementById('igst-total').textContent=fmt(ig);document.getElementById('grand-total').textContent=fmt(sub+cg+sg+ig)}addLine();</script><?php page_end();
